/**
 * pages/NotFound.jsx - the in-app 404. The static host 404 (public/404.html,
 * generated by prestruct from site.config.js notFound) carries the same shape
 * and copy, so the host-not-found and the hydrate-not-found read as one page.
 */
import { Link } from 'react-router-dom'
import usePageMeta from '../hooks/usePageMeta.js'
import site from '../site.js'

export default function NotFound() {
  const nf = site.notFound
  usePageMeta({
    siteUrl: site.url,
    path: '/404',
    title: `404 | ${site.name}`,
    description: nf.body,
    noindex: true,
  })
  return (
    <section className="nf">
      <div className="wrap">
        <h1>{nf.heading}</h1>
        <p>{nf.body}</p>
        <Link className="btn btn-primary" to={nf.primaryCta.href}>{nf.primaryCta.label}</Link>
      </div>
    </section>
  )
}
